example.code:
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string text = "STRINGS";
    const size_t len = text.size();

    // 1. Using dynamic allocation with copy()
    char* buffer = new char[len + 1];
    text.copy(buffer, len, 0);
    buffer[len] = '\0'; // Crucial: manual null termination

    // 2. Using c_str()
    const char* cStrPtr = text.c_str();

    // 3. Using data() (C++17 guarantees null-terminated const char*)
    const char* dataPtr = text.data();

    std::cout << "Original: " << text << "\n";
    std::cout << "c_str: " << cStrPtr << "\n";
    std::cout << "data: ";
    for (size_t i = 0; i < len; ++i) {
        std::cout << *(dataPtr + i);
    }
    std::cout << "\ncopy buffer: " << buffer << "\n";

    delete[] buffer;
    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string text = "Testing iterators";

    // Forward traversal using const_iterator (Principle of least privilege)
    std::cout << "Forward (const_iterator): ";
    for (std::string::const_iterator it = text.begin(); it != text.end(); ++it) {
        std::cout << *it;
    }
    std::cout << "\n";

    // Reverse traversal using const_reverse_iterator
    std::cout << "Reverse (rbegin to rend): ";
    for (std::string::const_reverse_iterator rit = text.rbegin(); rit != text.rend(); ++rit) {
        std::cout << *rit;
    }
    std::cout << "\n";

    // Modern C++ range-based for loop
    std::cout << "Range-based for: ";
    for (char ch : text) {
        std::cout << ch;
    }
    std::cout << "\n";

    return 0;
}

body.vi:
C++ cung cấp khả năng I/O trên bộ nhớ (in-memory I/O) thông qua thư viện `<sstream>`. Tương tự như `std::cin` và `std::cout`, các luồng chuỗi hoạt động dựa trên các lớp khuôn mẫu `basic_istringstream` và `basic_ostringstream`:
```cpp
typedef basic_istringstream<char> istringstream;
typedef basic_ostringstream<char> ostringstream;
```
`std::ostringstream` kế thừa toàn bộ khả năng định dạng mạnh mẽ của `std::ostream` (như các cờ định dạng số học, độ chính xác thập phân, thụt lề). Dữ liệu xuất ra được lưu trữ tạm thời trong một đối tượng `std::string` nội bộ thay vì gửi trực tiếp tới màn hình thiết bị hay tập tin.

body.en:
C++ offers in-memory stream capabilities via the `<sstream>` header. Analogous to `std::cin` and `std::cout`, string streams are type aliases for template specializations:
```cpp
typedef basic_istringstream<char> istringstream;
typedef basic_ostringstream<char> ostringstream;
```
`std::ostringstream` inherits all stream insertion and formatting capabilities of `std::ostream` (such as stream manipulators, precision, and alignment). Output data is accumulated directly inside an internal dynamic `std::string` buffer rather than writing to hardware devices or disk files.

example.code:
#include <iostream>
#include <string>
#include <sstream>
#include <iomanip>

int main() {
    std::ostringstream outputString;

    std::string title = "Output of several data types to an ostringstream object:";
    double doubleVal = 123.4567;
    int intVal = 22;

    // Format and insert data types
    outputString << title << "\n"
                 << "        double: " << std::fixed << std::setprecision(3) << doubleVal << "\n"
                 << "           int: " << intVal;

    // Retrieve string content
    std::cout << "outputString contains:\n" << outputString.str() << "\n";

    // Append more text
    outputString << "\nmore characters added";
    std::cout << "\nafter additional stream insertions,\n"
              << "outputString contains:\n" << outputString.str() << "\n";

    return 0;
}
